        />
        <div className="min-w-0 w-full">
          <span
            className={cn(
              "font-medium text-amber-900",
              inline ? "text-[11px]" : "text-[12px]",
            )}
          >
            {FLAG_CLASS_LABELS[flag.flag_class]}
          </span>
          <p
            className={cn(
              "text-amber-800 mt-0.5 leading-relaxed",
              inline ? "text-[11px]" : "text-[12px]",
