            {currentRunText}
          </blockquote>
        </div>
      )}
      {priorRunText && (
        <div>
          <div className="eyebrow text-[9px] text-sky-500 mb-1.5">Previous run</div>
          <blockquote className="pl-3 border-l-2 border-sky-200 text-[11.5px] text-sky-700/60 italic leading-relaxed whitespace-pre-wrap">
            {priorRunText}
