content.content:
export type AdaMode = "initial" | "update" | "replace";

export type AdaDealType =
  | "flat"
  | "vs"
  | "percentage_of_net"
  | "percentage_of_gross"
  | "door";

export type AdaFlagClass =
  | "ambiguous_net"
  | "external_reference"
  | "computed_threshold"
  | "missing_overage"
  | "unresolved_reference"
  | "bracketed_update"
  | "mode_fallback"
  | "other";

export type AdaFieldAffected =
  | "guarantee_amount"
  | "percentage"
  | "percentage_basis"
  | "expense_cap"
  | "hospitality_cap"
  | "ratchet"
  | "walkout_pot"
  | "bonuses"
  | "global";

export interface AdaRatchet {
  base_percent: number;
  cap_percent: number;
  trigger_capacity_pct: number;
}

export interface AdaWalkoutPot {
  threshold_amount: number;
  threshold_source: "stated" | "computed";
}

export interface AdaTieredNetSplit {
  low_percent: number;
  high_percent: number;
  threshold_gross: number;
}

export interface AdaBonus {
